  const printer = location.search.includes('panel=printer');
  const home = location.pathname.includes('home');
  let wrapped = false;
  const wrap = () => {
    if (wrapped || !window.wx || typeof window.wx.postMessage !== 'function') return;
    const orig = window.wx.postMessage.bind(window.wx);
    window.wx.postMessage = (json) => {
      try { const e = JSON.parse(json); if (!['state_request', 'ready', 'hello'].includes(e.type)) log('out', { type: e.type, payload: e.payload }); } catch (err) {}
      return orig(json);
