  let step = 0, last = '';
  const setValue = (el, value) => {
    const setter = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), 'value').set;
    setter.call(el, value); el.dispatchEvent(new Event('input', { bubbles: true }));
  };
  setInterval(() => {
    wrap();
